import{_ as t,o as e,c as a,Q as d}from"./chunks/framework.48927342.js";const g=JSON.parse('{"title":"Asking the Time","description":"","frontmatter":{},"headers":[],"relativePath":"en/more/maltese/practice/dialogues/04-asking-the-time.md","filePath":"en/more/maltese/practice/dialogues/04-asking-the-time.md"}'),n={name:"en/more/maltese/practice/dialogues/04-asking-the-time.md"},r=d('<h1 id="asking-the-time" tabindex="-1">Asking the Time <a class="header-anchor" href="#asking-the-time" aria-label="Permalink to &quot;Asking the Time&quot;">​</a></h1><p><strong>Scenario:</strong> Two friends meet at an agreed place. One asks the time and checks whether there is still time before an appointment.</p><h2 id="complete-dialogue" tabindex="-1">Complete Dialogue <a class="header-anchor" href="#complete-dialogue" aria-label="Permalink to &quot;Complete Dialogue&quot;">​</a></h2><p><strong>Mark:</strong> Skużani, x&#39;ħin hu issa?</p><p><strong>Lina:</strong> Huma t-tmienja u kwart.</p><p><strong>Mark:</strong> Grazzi. Għandi appuntament fit-tmienja u nofs.</p><p><strong>Lina:</strong> Għad għandek ħmistax-il minuta.</p><p><strong>Mark:</strong> Tajjeb. Il-post jinsab ħdejn il-pjazza, hux?</p><p><strong>Lina:</strong> Iva, eżattament. Jien qiegħda quddiem il-bieb.</p><p><strong>Mark:</strong> Qed nitlaq issa. Nasal f&#39;għaxar minuti.</p><p><strong>Lina:</strong> Sewwa, narak dalwaqt.</p><h2 id="sentence-by-sentence-translation-and-word-notes" tabindex="-1">Sentence-by-Sentence Translation and Word Notes <a class="header-anchor" href="#sentence-by-sentence-translation-and-word-notes" aria-label="Permalink to &quot;Sentence-by-Sentence Translation and Word Notes&quot;">​</a></h2><h3 id="_1-mark" tabindex="-1">1. Mark <a class="header-anchor" href="#_1-mark" aria-label="Permalink to &quot;1. Mark&quot;">​</a></h3><p><strong>Malti:</strong> Skużani, x&#39;ħin hu issa?</p><p><strong>Translation:</strong> Excuse me, what time is it now?</p><table><thead><tr><th>Maltese</th><th>English meaning</th><th>Notes</th></tr></thead><tbody><tr><td>Skużani</td><td>excuse me; forgive me</td><td>Polite expression</td></tr><tr><td>x&#39;ħin</td><td>what time</td><td><code>x&#39;</code> “what” + <code>ħin</code> “time”</td></tr><tr><td>hu</td><td>is</td><td>Third-person masculine pronoun, used here in the time expression</td></tr><tr><td>issa</td><td>now</td><td>Time adverb</td></tr></tbody></table><h3 id="_2-lina" tabindex="-1">2. Lina <a class="header-anchor" href="#_2-lina" aria-label="Permalink to &quot;2. Lina&quot;">​</a></h3><p><strong>Malti:</strong> Huma t-tmienja u kwart.</p><p><strong>Translation:</strong> It is quarter past eight.</p><table><thead><tr><th>Maltese</th><th>English meaning</th><th>Notes</th></tr></thead><tbody><tr><td>Huma</td><td>they are; it is</td><td>Copula-like form introducing the time</td></tr><tr><td>it-tmienja</td><td>eight o&#39;clock</td><td>Clock-hour form with the definite article</td></tr><tr><td>u</td><td>and; past</td><td>Connects the hour and minutes</td></tr><tr><td>kwart</td><td>quarter</td><td>A quarter of an hour; fifteen minutes</td></tr></tbody></table><h3 id="_3-mark" tabindex="-1">3. Mark <a class="header-anchor" href="#_3-mark" aria-label="Permalink to &quot;3. Mark&quot;">​</a></h3><p><strong>Malti:</strong> Grazzi. Għandi appuntament fit-tmienja u nofs.</p><p><strong>Translation:</strong> Thanks. I have an appointment at half past eight.</p><table><thead><tr><th>Maltese</th><th>English meaning</th><th>Notes</th></tr></thead><tbody><tr><td>Grazzi</td><td>thank you; thanks</td><td>Polite expression</td></tr><tr><td>Għandi</td><td>I have</td><td>First-person singular form of <code>għand</code></td></tr><tr><td>appuntament</td><td>appointment</td><td>Masculine noun</td></tr><tr><td>fit-tmienja</td><td>at eight</td><td>Contracted <code>f&#39;</code> “at” + clock-hour form</td></tr><tr><td>u</td><td>and; past</td><td>Connects parts of the time expression</td></tr><tr><td>nofs</td><td>half</td><td><code>u nofs</code> means “half past”</td></tr></tbody></table><h3 id="_4-lina" tabindex="-1">4. Lina <a class="header-anchor" href="#_4-lina" aria-label="Permalink to &quot;4. Lina&quot;">​</a></h3><p><strong>Malti:</strong> Għad għandek ħmistax-il minuta.</p><p><strong>Translation:</strong> You still have fifteen minutes.</p><table><thead><tr><th>Maltese</th><th>English meaning</th><th>Notes</th></tr></thead><tbody><tr><td>Għad</td><td>still; yet</td><td>Indicates continuation</td></tr><tr><td>għandek</td><td>you have</td><td>Second-person singular form of <code>għand</code></td></tr><tr><td>ħmistax-il</td><td>fifteen</td><td>Numeral form linking to the following noun</td></tr><tr><td>minuta</td><td>minute</td><td>Feminine noun</td></tr></tbody></table><h3 id="_5-mark" tabindex="-1">5. Mark <a class="header-anchor" href="#_5-mark" aria-label="Permalink to &quot;5. Mark&quot;">​</a></h3><p><strong>Malti:</strong> Tajjeb. Il-post jinsab ħdejn il-pjazza, hux?</p><p><strong>Translation:</strong> All right. The place is next to the square, isn&#39;t it?</p><table><thead><tr><th>Maltese</th><th>English meaning</th><th>Notes</th></tr></thead><tbody><tr><td>Tajjeb</td><td>good; all right</td><td>Masculine form, also used as a response</td></tr><tr><td>il-post</td><td>the place</td><td>Definite article + <code>post</code></td></tr><tr><td>jinsab</td><td>is located; is</td><td>Third-person masculine singular form</td></tr><tr><td>ħdejn</td><td>beside; next to</td><td>Preposition of location</td></tr><tr><td>il-pjazza</td><td>the square</td><td>Feminine noun with the definite article</td></tr><tr><td>hux</td><td>isn&#39;t it?; right?</td><td>Tag question used for confirmation</td></tr></tbody></table><h3 id="_6-lina" tabindex="-1">6. Lina <a class="header-anchor" href="#_6-lina" aria-label="Permalink to &quot;6. Lina&quot;">​</a></h3><p><strong>Malti:</strong> Iva, eżattament. Jien qiegħda quddiem il-bieb.</p><p><strong>Translation:</strong> Yes, exactly. I&#39;m in front of the door.</p><table><thead><tr><th>Maltese</th><th>English meaning</th><th>Notes</th></tr></thead><tbody><tr><td>Iva</td><td>yes</td><td>Affirmative response</td></tr><tr><td>eżattament</td><td>exactly</td><td>Adverb</td></tr><tr><td>Jien</td><td>I</td><td>Emphatic pronoun</td></tr><tr><td>qiegħda</td><td>located; situated</td><td>Feminine speaker form; a male speaker uses <code>qiegħed</code></td></tr><tr><td>quddiem</td><td>in front of</td><td>Preposition of location</td></tr><tr><td>il-bieb</td><td>the door</td><td>Masculine noun with the definite article</td></tr></tbody></table><h3 id="_7-mark" tabindex="-1">7. Mark <a class="header-anchor" href="#_7-mark" aria-label="Permalink to &quot;7. Mark&quot;">​</a></h3><p><strong>Malti:</strong> Qed nitlaq issa. Nasal f&#39;għaxar minuti.</p><p><strong>Translation:</strong> I&#39;m leaving now. I&#39;ll arrive in ten minutes.</p><table><thead><tr><th>Maltese</th><th>English meaning</th><th>Notes</th></tr></thead><tbody><tr><td>Qed</td><td>currently; in the process of</td><td>Used with a verb to express an ongoing action</td></tr><tr><td>nitlaq</td><td>I leave; I set off</td><td>First-person singular form</td></tr><tr><td>issa</td><td>now</td><td>Time adverb</td></tr><tr><td>Nasal</td><td>I arrive</td><td>First-person singular form</td></tr><tr><td>f&#39;għaxar</td><td>in ten</td><td><code>f&#39;</code> + <code>għaxar</code> “ten”</td></tr><tr><td>minuti</td><td>minutes</td><td>Plural of <code>minuta</code></td></tr></tbody></table><h3 id="_8-lina" tabindex="-1">8. Lina <a class="header-anchor" href="#_8-lina" aria-label="Permalink to &quot;8. Lina&quot;">​</a></h3><p><strong>Malti:</strong> Sewwa, narak dalwaqt.</p><p><strong>Translation:</strong> All right, see you soon.</p><table><thead><tr><th>Maltese</th><th>English meaning</th><th>Notes</th></tr></thead><tbody><tr><td>Sewwa</td><td>all right; okay</td><td>Common response</td></tr><tr><td>narak</td><td>I see you; see you</td><td><code>nara</code> “I see” + <code>-k</code> “you”</td></tr><tr><td>dalwaqt</td><td>soon; shortly</td><td>Time adverb</td></tr></tbody></table><h2 id="time-expressions" tabindex="-1">Time Expressions <a class="header-anchor" href="#time-expressions" aria-label="Permalink to &quot;Time Expressions&quot;">​</a></h2><ul><li><code>u kwart</code>: quarter past; <code>u nofs</code>: half past.</li><li><code>neqsin kwart</code>: quarter to the next hour, for example <code>id-disgħa neqsin kwart</code> (quarter to nine, 8:45).</li><li>Use 24-hour numeric time when you need to avoid ambiguity.</li></ul>',46),i=[r];function o(s,l,h,m,c,u){return e(),a("div",null,i)}const f=t(n,[["render",o]]);export{g as __pageData,f as default};
